package com.joeber321.relic.item; import com.joeber321.relic.RelicMod; import net.minecraft.item.Item; import net.minecraft.registry.Registries; import net.minecraft.registry.Registry; import net.minecraft.util.Identifier; public class ModItems { public static final Item ANCIENT_RELIC = registerItem("ancient_relic", new AncientRelicItem(new Item.Settings().maxCount(1))); private static Item registerItem(String name, Item item) { return Registry.register(Registries.ITEM, Identifier.of(RelicMod.MOD_ID, name), item); } public static void registerModItems() { RelicMod.LOGGER.info("Registering Mod Items for " + RelicMod.MOD_ID); } }
